import os,re,json,collections
D='logs'; err=collections.Counter(); warnlog=collections.Counter(); dbtime=[]; req=collections.Counter(); over=[]
for fn in sorted(os.listdir(D)):
    p=os.path.join(D,fn)
    for i,line in enumerate(open(p,encoding='utf-8'),1):
        line=line.rstrip('\n')
        if not line.strip(): continue
        if fn.endswith('.jsonl'):
            o=json.loads(line); lvl=o['level']; svc=o['service']; msg=o['msg']; ts=o['ts']
        else:
            m=re.match(r'^(\S+)\s+(INFO|WARN|ERROR|DEBUG|TRACE)\s+\[([^\]]+)\]\s?(.*)$',line)
            ts,lvl,svc,msg=m.groups()
        if lvl=='ERROR': err[svc]+=1
        if lvl=='WARN' and 'login failed' in msg:
            u=re.search(r'user=(\S+)',msg).group(1); warnlog[(svc,u)]+=1
        if 'db timeout' in msg: dbtime.append((ts,svc,msg,fn,i))
        if 'request done' in msg:
            lm=int(re.search(r'latency_ms=(\d+)',msg).group(1))
            req[svc]+=1
            if lm>2000: over.append((ts,svc,lm,fn,i))
print('error counts',err, 'sum',sum(err.values()))
print('warn logins',warnlog)
print('db timeouts',len(dbtime))
for x in sorted(dbtime)[:10]: print(x)
print('req counts',req)
print('over2000',len(over))
print('over sample',over[:3])
PY", "description": "Compute candidate incident metrics"}

